    // that everyone needs to be able to interact with. Also allow reflexive associations
    // within the same uid.
    if (uid1 == uid2 || UserHandle.getAppId(uid1) == SYSTEM_UID
            || UserHandle.getAppId(uid2) == SYSTEM_UID) {
